# Candidate (B1) for TASK-BANK-018 (beneficiary_name_structure)
def build_request(data):
    return {
        'path': '/v1/banking/beneficiary_name_structure/task-bank-018',
        'body': {
            'beneficiary_transfer': {
                'amount_subunits': float(data['amount_cents']) / 100.0,
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': 'unverified_route_task-bank-018',
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': 'dropped-idem-b1-task-bank-018'
        }
    }

def process_wire(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
